mapper.select:
SELECT



        , (SELECT COUNT(1) FROM bobo_favorite f
            WHERE f.item_id = i.item_id AND f.user_id = #{currentUserId}) AS favorited


        , 0 AS favorited


FROM bobo_item i
LEFT JOIN bobo_category c ON c.category_id = i.category_id
LEFT JOIN bobo_user u ON u.user_id = i.seller_id AND u.del_flag = 0

    i.del_flag = 0

        AND (i.title LIKE CONCAT('%', #{q.keyword}, '%')
             OR i.description LIKE CONCAT('%', #{q.keyword}, '%'))


        AND (i.title LIKE CONCAT('%', #{q.adminKeyword}, '%')
             OR u.nickname LIKE CONCAT('%', #{q.adminKeyword}, '%')

                 OR i.item_id = #{q.adminKeyword}
             )


        AND i.category_id = #{q.categoryId}


        AND i.seller_id = #{q.sellerId}


        AND i.seller_id != #{q.excludeSellerId}


        AND i.status = #{q.status}


        AND i.price >= #{q.minPrice}


        AND i.price <= #{q.maxPrice}


        AND i.campus = #{q.campus}


        AND i.condition_level = #{q.conditionLevel}


        AND (i.trade_type = #{q.tradeType} OR i.trade_type = 0)


        AND EXISTS (SELECT 1 FROM bobo_favorite f2
                    WHERE f2.item_id = i.item_id AND f2.user_id = #{currentUserId})



    ORDER BY i.price ASC, i.item_id DESC
    ORDER BY i.price DESC, i.item_id DESC
    ORDER BY i.want_count DESC, i.item_id DESC
    ORDER BY i.view_count DESC, i.item_id DESC
    ORDER BY i.create_time DESC, i.item_id DESC

SELECT , 0 AS favorited FROM bobo_item i LEFT JOIN bobo_category c ON c.category_id = i.category_id LEFT JOIN bobo_user u ON u.user_id = i.seller_id AND u.del_flag = 0 WHERE i.del_flag = 0 AND i.status = 1 AND i.seller_id = #{sellerId}
AND i.item_id != #{excludeItemId}
ORDER BY i.create_time DESC LIMIT #{limit}
